#include <iostream>
#include <string>
using namespace std;

bool visited[400][400];
int dir[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

int main() {
    string op;
    cin >> op;

    int x = 200, y = 200;
    visited[x][y] = true;

    for (char move : op) {
        switch (move) {
            case 'L': --y; break;
            case 'R': ++y; break;
            case 'U': --x; break;
            case 'D': ++x; break;
        }

        if (visited[x][y]) {
            cout << "BUG\n";
            return 0;
        }

        int count = 0;
        for (const auto& d : dir) {
            if (visited[x + d[0]][y + d[1]]) {
                ++count;
            }
        }

        if (count >= 2) {
            cout << "BUG\n";
            return 0;
        }

        visited[x][y] = true;
    }

    cout << "OK\n";
    return 0;
}

